// The rebuilt cover (public/media/cover/cover.svg) against data/cover.json: every binary digit element reads as
// the string the cover carries, and the pulsar map's angles and lengths survive the placement on the cover.
// The SVG is parsed with a small XML reader below (no dependency); the SVG is generated by tools/cover/build_cover.py.

import { readFileSync, statSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { loadCover } from './support/data';
import { recordCheck } from './support/record';

const SVG_PATH = resolve(process.cwd(), 'public', 'media', 'cover', 'cover.svg');

interface El {
  tag: string;
  attrs: Record<string, string>;
  children: El[];
}

/** Minimal XML reader: elements, attributes, comments, declarations and text (text is dropped). */
function parseXml(src: string): El {
  const root: El = { tag: '#root', attrs: {}, children: [] };
  const stack: El[] = [root];
  const re = /<!--[\s\S]*?-->|<\?[\s\S]*?\?>|<\/([A-Za-z][\w:-]*)\s*>|<([A-Za-z][\w:-]*)((?:\s+[\w:.-]+\s*=\s*"[^"]*")*)\s*(\/?)>/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(src)) !== null) {
    if (m[0].startsWith('<!--') || m[0].startsWith('<?')) continue;
    if (m[1]) {
      const top = stack.pop();
      if (!top || top.tag !== m[1]) throw new Error(`mismatched closing tag ${m[1]}`);
      continue;
    }
    const attrs: Record<string, string> = {};
    const ar = /([\w:.-]+)\s*=\s*"([^"]*)"/g;
    let a: RegExpExecArray | null;
    while ((a = ar.exec(m[3] ?? '')) !== null) attrs[a[1] as string] = a[2] ?? '';
    const el: El = { tag: m[2] as string, attrs, children: [] };
    (stack[stack.length - 1] as El).children.push(el);
    if (m[4] !== '/') stack.push(el);
  }
  if (stack.length !== 1) throw new Error('unclosed elements');
  return root.children[0] as El;
}

function walk(el: El, fn: (e: El) => void): void {
  fn(el);
  for (const c of el.children) walk(c, fn);
}

function findAll(el: El, pred: (e: El) => boolean): El[] {
  const out: El[] = [];
  walk(el, (e) => {
    if (pred(e)) out.push(e);
  });
  return out;
}

const byId = (root: El, id: string): El => {
  const hit = findAll(root, (e) => e.attrs['data-id'] === id);
  if (hit.length !== 1) throw new Error(`expected one element with data-id ${id}, found ${hit.length}`);
  return hit[0] as El;
};

/** The bit elements below a group, in document order, as a string; also checks data-index runs 0..n-1. */
function readBits(group: El): string {
  const bits = findAll(group, (e) => /\bbit\b/.test(e.attrs.class ?? ''));
  const s = bits.map((b) => (/\bone\b/.test(b.attrs.class ?? '') ? '1' : /\bzero\b/.test(b.attrs.class ?? '') ? '0' : '?')).join('');
  bits.forEach((b, i) => {
    if (Number(b.attrs['data-index']) !== i) throw new Error(`data-index ${b.attrs['data-index']} at position ${i} in ${group.attrs['data-id']}`);
  });
  return s;
}

const svgText = readFileSync(SVG_PATH, 'utf8');
const svg = parseXml(svgText);
const cover = loadCover();

describe('cover.svg', () => {
  it('cover.svg.binaries: every binary digit element reads as the cover says', () => {
    const expected: [string, string][] = [
      ['record.rotationPeriod', cover.record.rotationPeriod.binary],
      ['record.playTime', cover.record.playTime.binary],
      ['picture.lineTime', cover.picture.lineTime.binary],
      ['picture.rasterLines', cover.picture.rasterLines.binary],
    ];
    for (const set of ['waveform', 'scan']) {
      cover.picture.lineLabels.forEach((l, i) => expected.push([`picture.lineLabel.${set}.${i + 1}`, l.binary]));
    }
    for (const l of cover.pulsarMap.lines) expected.push([`pulsar.${l.order}`, l.binary]);
    const results: string[] = [];
    let bad = 0;
    for (const [id, bits] of expected) {
      const g = byId(svg, id);
      const got = readBits(g);
      const attr = g.attrs['data-binary'];
      const ok = got === bits && attr === bits;
      if (!ok) bad++;
      results.push(`${id}:${ok ? 'ok' : 'WRONG'}`);
      expect(got, id).toBe(bits);
      expect(attr, `${id} data-binary`).toBe(bits);
    }
    // each line-label wrapper holds exactly three labels reading 1, 10, 11
    for (const set of ['waveform', 'scan']) {
      const w = findAll(svg, (e) => e.attrs['data-id'] === 'picture.lineLabels' && e.attrs['data-set'] === set);
      expect(w.length).toBe(1);
      expect((w[0] as El).children.map((c) => readBits(c))).toEqual(cover.picture.lineLabels.map((l) => l.binary));
    }
    // the disputed small raster label is drawn but carries no bit elements (no source reads it)
    expect(readBits(byId(svg, 'picture.rasterLabel'))).toBe('');
    const totalBits = expected.reduce((s, [, b]) => s + b.length, 0);
    recordCheck({
      id: 'cover.svg.binaries',
      claim: 'On the rebuilt cover, every binary number reads exactly as the real cover does: the record speed, the playing time, the picture-line time, the raster count, the three line labels (twice) and all 14 pulsar periods.',
      measured: `${expected.length} digit groups, ${totalBits} digit elements read in document order (bar = 1, dash = 0); ${bad} differ`,
      expected: 'data/cover.json strings, from the 1977 photo pixel scan and the Pioneer vector (cover.md 1b to 1d)',
      tolerance: 'exact string equality, no allowance',
      pass: bad === 0,
      notes: `The disputed small label above the first raster lines (read as 10000 by one source, 1/10/11 by another) is drawn as plain marks and not asserted. ${results.length} groups checked.`,
    });
  });

  it('cover.svg.map: the map lines keep their angles and lengths after the placement on the cover', () => {
    type Pt = [number, number];
    const toPoints = (el: El): Pt[] =>
      [...(el.attrs.d ?? '').matchAll(/(-?\d+(?:\.\d+)?)\s+(-?\d+(?:\.\d+)?)/g)].map((m): Pt => [Number(m[1]), Number(m[2])]);
    const at = (a: Pt[], i: number): Pt => a[i] as Pt;
    const gc = byId(svg, 'pulsarMap.gcLine');
    const gcSolid = findAll(gc, (e) => /\bsolid\b/.test(e.attrs.class ?? ''))[0] as El;
    const gcPts = toPoints(gcSolid);
    const o = at(gcPts, 0);
    const gcEnd = at(gcPts, 1);
    const gcLen = Math.hypot(gcEnd[0] - o[0], gcEnd[1] - o[1]);
    const gcAng = Math.atan2(-(gcEnd[1] - o[1]), gcEnd[0] - o[0]);
    let worstAngle = 0;
    let worstLen = 0;
    let worstTick = 0;
    const rows: string[] = [];
    for (const l of cover.pulsarMap.lines) {
      const g = byId(svg, `pulsar.${l.order}`);
      const pieces = findAll(g, (e) => /\bsolid\b/.test(e.attrs.class ?? ''));
      expect(pieces.length).toBe(l.broken ? 2 : 1);
      const pts = pieces.flatMap(toPoints);
      // the line starts at the origin and ends at its farthest solid point
      const first = at(toPoints(pieces[0] as El), 0);
      expect(Math.hypot(first[0] - o[0], first[1] - o[1])).toBeLessThan(1e-3);
      let far = at(pts, 0);
      for (const p of pts) if (Math.hypot(p[0] - o[0], p[1] - o[1]) > Math.hypot(far[0] - o[0], far[1] - o[1])) far = p;
      const len = Math.hypot(far[0] - o[0], far[1] - o[1]);
      let ang = ((Math.atan2(-(far[1] - o[1]), far[0] - o[0]) - gcAng) * 180) / Math.PI;
      ang = ((ang % 360) + 360) % 360;
      const dAng = Math.abs(ang - l.mapAngleDeg);
      const dLen = Math.abs(len / gcLen - l.rOverR0) / l.rOverR0;
      worstAngle = Math.max(worstAngle, dAng);
      worstLen = Math.max(worstLen, dLen);
      expect(dAng, `${l.bname} angle`).toBeLessThan(0.05);
      expect(dLen, `${l.bname} length`).toBeLessThan(0.001);
      // break gap and tick position along the line
      if (l.broken && l.breakR0) {
        const a = at(toPoints(pieces[0] as El), 1);
        const b = at(toPoints(pieces[1] as El), 0);
        const g0 = Math.hypot(a[0] - o[0], a[1] - o[1]) / gcLen;
        const g1 = Math.hypot(b[0] - o[0], b[1] - o[1]) / gcLen;
        expect(Math.abs(g0 - l.breakR0[0]), `${l.bname} break start`).toBeLessThan(0.001);
        expect(Math.abs(g1 - l.breakR0[1]), `${l.bname} break end`).toBeLessThan(0.001);
      }
      const ticks = findAll(g, (e) => /\btick\b/.test(e.attrs.class ?? ''));
      if (l.absZOverR0 === null) expect(ticks.length).toBe(0);
      else {
        expect(ticks.length).toBe(1);
        const tp = toPoints(ticks[0] as El);
        const t0 = at(tp, 0);
        const t1 = at(tp, 1);
        const mid: Pt = [(t0[0] + t1[0]) / 2, (t0[1] + t1[1]) / 2];
        const z = Math.hypot(far[0] - mid[0], far[1] - mid[1]) / gcLen;
        worstTick = Math.max(worstTick, Math.abs(z - l.absZOverR0));
        expect(Math.abs(z - l.absZOverR0), `${l.bname} tick`).toBeLessThan(0.001);
      }
      rows.push(`${l.bname} ${ang.toFixed(2)} deg`);
    }
    // the first digit of every line (the most significant, always a 1) lies beyond the end of the solid line, nearer the origin than the last
    recordCheck({
      id: 'cover.svg.map',
      claim: 'On the rebuilt cover, each pulsar line points the way, and is as long as, the real map says, measured from the SVG geometry after it was placed and scaled on the cover.',
      measured: `14 lines: worst angle error ${worstAngle.toExponential(2)} deg, worst length error ${(worstLen * 100).toExponential(2)} %, worst tick position error ${worstTick.toExponential(2)} R0; centre line ${gcLen.toFixed(2)} mm`,
      expected: 'data/cover.json mapAngleDeg, rOverR0, breakR0, absZOverR0 (Pioneer plaque vector, cover.md 1d)',
      tolerance: '0.05 deg, 0.1 % of length, 0.001 R0 for breaks and ticks (the placement is a similarity, so all three are preserved)',
      pass: worstAngle < 0.05 && worstLen < 0.001,
      notes: 'This tests the map against its own data, not against the 1977 photo: the photo differs from the Pioneer artwork by up to 3 degrees on some lines and 2 to 6 % in length (cover.md 1f); see the alignment report in build/cover/landmarks.json.',
    });
  });

  it('is under 1 MB and has no external references', () => {
    expect(statSync(SVG_PATH).size).toBeLessThan(1_000_000);
    expect(svgText).not.toMatch(/\bhref\s*=|xlink:|<image|<script|<foreignObject|@import|url\(/i);
    const urls = [...svgText.matchAll(/https?:\/\/[^\s"')]+/g)].map((m) => m[0]);
    expect(urls.filter((u) => u !== 'http://www.w3.org/2000/svg')).toEqual([]);
    expect(svg.attrs.viewBox).toBe('0 0 304.8 304.8');
  });

  it('draws no uranium spot and has the empty placeholder group', () => {
    const g = byId(svg, 'cover.uraniumSpot');
    expect(g.children.length).toBe(0);
    expect(g.attrs['data-drawn']).toBe('false');
  });
});
